import Foundation

/// Bridge to the aria-mobile-core Rust library via UniFFI-generated bindings.
///
/// The actual UniFFI-generated Swift file will be at:
///   AriaSoftphone/Bridge/aria_mobile.swift
///
/// Generated by running:
///   cargo run --features=uniffi/cli -- generate \
///     --library target/aarch64-apple-ios/release/libaria_mobile_core.a \
///     --language swift \
///     --out-dir ../aria-ios/AriaSoftphone/Bridge/
///
/// This file provides convenience wrappers and type aliases.

/// Namespace for Rust runtime lifecycle.
enum AriaMobileCore {
    /// Initialize the Rust tokio runtime. Call once at app launch.
    static func initRuntime() {
        // Calls into UniFFI-generated: aria_mobile.initRuntime()
        initRuntime_uniffi()
    }

    /// Shut down the Rust runtime.
    static func shutdownRuntime() {
        // Calls into UniFFI-generated: aria_mobile.shutdownRuntime()
        shutdownRuntime_uniffi()
    }
}

// MARK: - UniFFI Stubs (replaced by generated code at build time)
//
// These stubs allow the project to compile before UniFFI generation.
// In a real build, the generated `aria_mobile.swift` replaces these.

#if !UNIFFI_GENERATED

func initRuntime_uniffi() {
    print("[stub] initRuntime called — link aria_mobile_core for real impl")
}

func shutdownRuntime_uniffi() {
    print("[stub] shutdownRuntime called")
}

// Stub types matching the UDL definitions

struct GatewayConfig {
    let baseUrl: String
    let apiKey: String
}

struct SipCredentials {
    let username: String
    let password: String
    let domain: String
    let registrar: String?
    let transport: String
    let port: UInt16
    let authUsername: String?
    let displayName: String
}

struct DeviceRegistration {
    let platform: String
    let pushToken: String
    let bundleId: String?
    let sip: SipCredentials
}

struct DeviceRegistrationResponse {
    let deviceId: String
    let authToken: String
}

struct CallOffer {
    let callToken: String
    let callerUri: String
    let callerName: String?
    let sdpOffer: String
}

enum CallState {
    case idle, incoming, ringing, connecting, connected, onHold, ended
}

enum CallDirection {
    case inbound, outbound
}

struct CallInfo {
    let callId: String
    let remoteUri: String
    let remoteName: String?
    let state: CallState
    let direction: CallDirection
    let muted: Bool
    let onHold: Bool
    let durationSecs: UInt64
}

enum AudioCodec {
    case pcmu, pcma, opus, g729
}

struct MediaStats {
    let packetsSent: UInt64
    let packetsReceived: UInt64
    let bytesSent: UInt64
    let bytesReceived: UInt64
    let jitterMs: Double
    let packetLoss: UInt32
    let rttMs: Double
}

struct PushCallPayload {
    let callToken: String
    let callerUri: String
    let callerName: String?
    let gatewayUrl: String
}

enum MobileError: Error {
    case networkError, authenticationError, registrationFailed
    case callFailed, mediaError, invalidState, gatewayError, timeout
}

protocol MobileEventHandler: AnyObject {
    func onRegistrationChanged(deviceId: String, status: String, error: String?)
    func onIncomingCall(offer: CallOffer)
    func onCallStateChanged(info: CallInfo)
    func onMediaStats(callId: String, stats: MediaStats)
    func onError(context: String, message: String)
}

class AriaMobileEngine {
    init(gatewayConfig: GatewayConfig) {
        print("[stub] AriaMobileEngine created")
    }

    func setEventHandler(handler: MobileEventHandler) {}

    func registerDevice(registration: DeviceRegistration) throws -> DeviceRegistrationResponse {
        return DeviceRegistrationResponse(deviceId: "stub", authToken: "stub")
    }

    func unregisterDevice(deviceId: String) throws {}

    func updatePushToken(deviceId: String, newToken: String) throws {}

    func handlePushNotification(payload: PushCallPayload) throws -> CallOffer {
        return CallOffer(callToken: "", callerUri: "", callerName: nil, sdpOffer: "")
    }

    func acceptIncomingCall(callToken: String, preferredCodecs: [AudioCodec]) throws -> CallInfo {
        return CallInfo(callId: "", remoteUri: "", remoteName: nil, state: .connected,
                       direction: .inbound, muted: false, onHold: false, durationSecs: 0)
    }

    func rejectIncomingCall(callToken: String) throws {}

    func makeCall(uri: String, credentials: SipCredentials, preferredCodecs: [AudioCodec]) throws -> CallInfo {
        return CallInfo(callId: "", remoteUri: uri, remoteName: nil, state: .ringing,
                       direction: .outbound, muted: false, onHold: false, durationSecs: 0)
    }

    func hangup(callId: String) throws {}
    func setMute(callId: String, muted: Bool) throws {}
    func setHold(callId: String, onHold: Bool) throws {}
    func sendDtmf(callId: String, digit: String) throws {}

    func getActiveCall() -> CallInfo? { return nil }
    func getMediaStats(callId: String) -> MediaStats? { return nil }
    func setCodecPreferences(codecs: [AudioCodec]) {}
}

#endif
